import React, { useRef } from 'react';
import NavBar from '../../Components/NavBar';
import Footer from '../../Components/Footer';
import './'

const Sleeve = () => {
  const sections = {
    puff: useRef(null),
    bishop: useRef(null),
    bell: useRef(null),
    raglan: useRef(null),
    offShoulder: useRef(null),
  };

  const handleScroll = (event) => {
    const selected = event.target.value;
    if (sections[selected]) {
      sections[selected].current.scrollIntoView({ behavior: 'smooth' });
    }
  };

  // Add image arrays for each sleeve variety
  const sleeveImages = {
    puff: [
      "/Images/Designs/sleeves/puff1.jpg",
      "/Images/Designs/sleeves/puff2.jpg",
      "/Images/Designs/sleeves/puff3.jpg"
    ],
    bishop: [
      "/Images/Designs/sleeves/bishop1.jpg",
      "/Images/Designs/sleeves/bishop2.jpg"
    ],
    bell: [
      "/Images/Designs/sleeves/bell1.jpg",
      "/Images/Designs/sleeves/bell2.jpg",
      "/Images/Designs/sleeves/bell3.jpg"
    ],
    raglan: [
      "/Images/Designs/sleeves/raglan1.jpg",
      "/Images/Designs/sleeves/raglan2.jpg"
    ],
    offShoulder: [
      "/Images/Designs/sleeves/offshoulder1.jpg",
      "/Images/Designs/sleeves/offshoulder2.jpg"
    ],
  };

  return (
    <>
      <NavBar />
      <div style={{ padding: '20px', textAlign: 'center' }}>
        <h1>Sleeve Varieties</h1>
        <select onChange={handleScroll} defaultValue="">
          <option value="" disabled>Select Sleeve Variety</option>
          <option value="puff">Puff Sleeve</option>
          <option value="bishop">Bishop Sleeve</option>
          <option value="bell">Bell Sleeve</option>
          <option value="raglan">Raglan Sleeve</option>
          <option value="offShoulder">Off Shoulder Sleeve</option>
        </select>
      </div>

      <div style={{ padding: '20px' }}>
        {Object.entries(sleeveImages).map(([key, images]) => (
          <section key={key} ref={sections[key]} id={key} style={{ marginBottom: '50px' }}>
            <h2>{key.replace(/([A-Z])/g, ' $1').replace(/^./, str => str.toUpperCase())} Sleeve</h2>
            <div style={{ display: 'flex', gap: '10px', overflowX: 'auto' }}>
              {images.map((src, i) => (
                <img key={i} src={src} alt={`${key} sleeve design ${i+1}`} style={{ width: '200px', height: 'auto', borderRadius: '8px' }} />
              ))}
            </div>
            <p>Description and details about {key} Sleeves.</p>
          </section>
        ))}
      </div>

      <Footer />
    </>
  );
};

export default Sleeve;
